import { defineConfig } from 'vitest/config';

export default defineConfig({
	test: {
		environment: 'node',
		include: ['test/**/*.test.ts', 'test/**/*.test.tsx'],
	},
});

import { describe, expect, it } from 'vitest';

import { EMAIL_KINDS, defineTemplate, templateAlias } from '../src/template-metadata';

describe('templateAlias', () => {
	it.each([
		['inviteMember', 'invite-member'],
		['workshopAnnouncement', 'workshop-announcement'],
		['workshopRegistration', 'workshop-registration'],
		['workshopRegistrationError', 'workshop-registration-error'],
		['magicLink', 'magic-link'],
	])('derives the kebab-case alias of %s', (kind, expected) => {
		expect(templateAlias(kind)).toBe(expected);
	});
});

describe('defineTemplate', () => {
	const valid = {
		kind: 'inviteMember',
		subject: 'You are invited',
		from: 'Dublin HEMA Club <no-reply@mail.dublinhemaclub.com>',
		variables: [{ key: 'INVITATION_LINK', type: 'string' }],
	} as const;

	it('derives and attaches the alias from the Email Kind', () => {
		const template = defineTemplate(valid);
		expect(template.alias).toBe('invite-member');
	});

	it('exposes subject, sender, and variables untouched', () => {
		const template = defineTemplate(valid);
		expect(template.subject).toBe('You are invited');
		expect(template.from).toContain('@');
		expect(template.variables).toHaveLength(1);
	});

	it('returns frozen metadata so definitions cannot drift after import', () => {
		const template = defineTemplate(valid);
		expect(Object.isFrozen(template)).toBe(true);
	});

	it('accepts number-typed variables with matching fallbacks', () => {
		const template = defineTemplate({
			...valid,
			variables: [{ key: 'WORKSHOP_COUNT', type: 'number', fallback: 0 }],
		});
		expect(template.variables[0]?.fallback).toBe(0);
	});

	it('rejects an unknown Email Kind', () => {
		expect(() =>
			defineTemplate({ ...valid, kind: 'notAKind' }),
		).toThrow(/unknown email kind/i);
	});

	it('rejects a key that is not UPPER_SNAKE', () => {
		expect(() =>
			defineTemplate({
				...valid,
				variables: [{ key: 'invitationLink', type: 'string' }],
			}),
		).toThrow(/UPPER_SNAKE/);
	});

	it.each(['FIRST_NAME', 'LAST_NAME', 'EMAIL', 'RESEND_UNSUBSCRIBE_URL'])(
		'rejects Resend reserved name %s case-insensitively',
		(key) => {
			expect(() =>
				defineTemplate({
					...valid,
					variables: [{ key, type: 'string' }],
				}),
			).toThrow(/reserved by Resend/);
		},
	);

	it('rejects more than 20 declared variables', () => {
		const variables = Array.from({ length: 21 }, (_, i) => ({
			key: `VARIABLE_${i}`,
			type: 'string' as const,
		}));

		expect(() => defineTemplate({ ...valid, variables })).toThrow(/at most 20/);
	});

	it('rejects duplicate variable keys', () => {
		expect(() =>
			defineTemplate({
				...valid,
				variables: [
					{ key: 'MESSAGE', type: 'string' },
					{ key: 'MESSAGE', type: 'number' },
				],
			}),
		).toThrow(/duplicate/);
	});

	it('rejects a fallback whose type does not match the declaration', () => {
		expect(() =>
			defineTemplate({
				...valid,
				variables: [{ key: 'WORKSHOP_COUNT', type: 'number', fallback: 'one' }],
			}),
		).toThrow(/fallback/);

		expect(() =>
			defineTemplate({
				...valid,
				variables: [{ key: 'MESSAGE', type: 'string', fallback: 3 }],
			}),
		).toThrow(/fallback/);
	});

	it('rejects empty subject or sender', () => {
		expect(() => defineTemplate({ ...valid, subject: '' })).toThrow(/subject/);
		expect(() => defineTemplate({ ...valid, from: 'no address here' })).toThrow(
			/from/,
		);
	});
});

describe('EMAIL_KINDS whitelist', () => {
	it('mirrors the five whitelisted kinds of Dhc.Email.Worker', () => {
		expect([...EMAIL_KINDS]).toEqual([
			'inviteMember',
			'workshopAnnouncement',
			'workshopRegistration',
			'workshopRegistrationError',
			'magicLink',
		]);
	});
});

/**
 * Template metadata schema for the code-authored transactional email
 * templates (ADR 0022 — Code-Authored Templates Synced to Resend-Hosted
 * Templates).
 *
 * Each component file in `emails/` exports its metadata via
 * {@link defineTemplate}, making TypeScript the single schema authority for
 * what each Email Kind requires: default subject, default sender, and the
 * declared typed variables. The Elixir side keeps only its generic
 * string|number validation; Resend enforces the per-template variable
 * contract at send time.
 *
 * Constraints encoded here mirror Resend's template rules:
 *
 * - variable keys are UPPER_SNAKE and referenced as {{{KEY}}} in markup;
 * - at most 20 declared variables per template;
 * - reserved names cannot be declared.
 */

/** The five whitelisted Email Kinds — mirrors `@transactional_ids` in `Dhc.Email.Worker`. */
export const EMAIL_KINDS = [
	'inviteMember',
	'workshopAnnouncement',
	'workshopRegistration',
	'workshopRegistrationError',
	'magicLink',
] as const;

export type EmailKind = (typeof EMAIL_KINDS)[number];

export type TemplateVariableType = 'string' | 'number';

export interface TemplateVariable {
	/** UPPER_SNAKE key as declared on the Resend-hosted template (`{{{KEY}}}`). */
	readonly key: string;
	readonly type: TemplateVariableType;
	/**
	 * Optional fallback rendered when a send omits the variable. Its runtime
	 * type must match the declared {@link TemplateVariable.type}.
	 */
	readonly fallback?: string | number;
}

export interface TemplateMetadata {
	/** The stable provider-neutral Email Kind (`inviteMember`, …). */
	readonly kind: EmailKind;
	/** Kebab-case alias derived from the kind; Resend templates are addressed by it. */
	readonly alias: string;
	readonly subject: string;
	/** Default sender in `Name <addr>` form. */
	readonly from: string;
	readonly variables: readonly TemplateVariable[];
}

export interface TemplateDefinition {
	kind: EmailKind;
	subject: string;
	from: string;
	variables: readonly TemplateVariable[];
}

/** Names Resend reserves on every template; declaring them is an error. */
export const RESERVED_VARIABLE_NAMES = new Set([
	'FIRST_NAME',
	'LAST_NAME',
	'EMAIL',
	'RESEND_UNSUBSCRIBE_URL',
	'contact',
	'this',
]);

/** Resend allows at most 20 declared variables per template. */
const MAX_VARIABLES = 20;

const UPPER_SNAKE = /^[A-Z][A-Z0-9]*(_[A-Z0-9]+)*$/;
const CAMEL_CASE_KIND = /^[a-z][A-Za-z0-9]*$/;
const SENDER_WITH_ADDRESS = /<[^<>]+@[^<>]+\.[^<>]+>|^[^\s<]+@[^\s<]+\.[^\s<]+$/;

/**
 * Derives the kebab-case template alias of an Email Kind. Sends address the
 * Resend-hosted template by this alias, so no kind→ID configuration map ever
 * exists at runtime (ADR 0022).
 */
export function templateAlias(kind: string): string {
	return kind
		.replace(/([a-z0-9])([A-Z])/g, '$1-$2')
		.toLowerCase();
}

function validate(definition: TemplateDefinition): void {
	const { kind, subject, from, variables } = definition;

	if (!CAMEL_CASE_KIND.test(kind) || !EMAIL_KINDS.includes(kind as EmailKind)) {
		throw new Error(
			`Unknown email kind "${kind}"; expected one of: ${EMAIL_KINDS.join(', ')}`,
		);
	}

	if (typeof subject !== 'string' || subject.trim() === '') {
		throw new Error(`Template "${kind}" must declare a non-empty subject`);
	}

	if (typeof from !== 'string' || !SENDER_WITH_ADDRESS.test(from)) {
		throw new Error(
			`Template "${kind}" must declare a sender address ("Name <addr>" or "addr")`,
		);
	}

	if (variables.length > MAX_VARIABLES) {
		throw new Error(
			`Template "${kind}" declares ${variables.length} variables; Resend allows at most ${MAX_VARIABLES}`,
		);
	}

	const seen = new Set<string>();

	for (const { key, type, fallback } of variables) {
		if (!UPPER_SNAKE.test(key)) {
			throw new Error(
				`Template "${kind}" variable "${key}" must be UPPER_SNAKE (e.g. INVITATION_LINK)`,
			);
		}

		if (RESERVED_VARIABLE_NAMES.has(key.toUpperCase())) {
			throw new Error(`Template "${kind}" variable "${key}" is reserved by Resend`);
		}

		if (seen.has(key)) {
			throw new Error(`Template "${kind}" declares duplicate variable "${key}"`);
		}
		seen.add(key);

		if (type !== 'string' && type !== 'number') {
			throw new Error(`Template "${kind}" variable "${key}" has unknown type "${type}"`);
		}

		if (
			fallback !== undefined &&
			(type === 'string' ? typeof fallback !== 'string' : typeof fallback !== 'number')
		) {
			throw new Error(
				`Template "${kind}" variable "${key}" declares type "${type}" but its fallback does not match`,
			);
		}
	}
}

/**
 * Declares a template's metadata, validating Resend's constraints eagerly so
 * a bad definition fails at import time instead of at send or sync time.
 */
export function defineTemplate(definition: TemplateDefinition): TemplateMetadata {
	validate(definition);

	return Object.freeze({
		kind: definition.kind,
		alias: templateAlias(definition.kind),
		subject: definition.subject,
		from: definition.from,
		variables: Object.freeze([...definition.variables].map((v) => Object.freeze(v))),
	});
}

