import type { ReactNode } from 'react';

import { Body, Container, Html, Preview, Text } from 'react-email';

export interface EmailLayoutProps {
	/** Rendered into the hidden `<Preview>` preheader. */
	preview?: string;
	children: ReactNode;
}

const body: React.CSSProperties = {
	backgroundColor: '#ffffff',
	fontFamily:
		'-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif',
	margin: 0,
};

const container: React.CSSProperties = {
	margin: '0 auto',
	maxWidth: '600px',
	padding: '24px',
};

const text: React.CSSProperties = {
	color: '#111827',
	fontSize: '16px',
	lineHeight: '26px',
	margin: '0 0 20px',
};

/** Shared paragraph style so every template's body copy matches. */
export const paragraphStyle = text;

/**
 * Shared shell for all DHC transactional emails: plain white background,
 * system font stack, and a single centered column — matching the plain
 * look of the original Loops templates.
 *
 * Lives in an underscore-prefixed folder so the `email dev` preview does
 * not list it as a template.
 */
export function EmailLayout({ preview = 'Dublin HEMA Club', children }: EmailLayoutProps) {
	return (
		<Html lang="en">
			<Preview>{preview}</Preview>
			<Body style={body}>
				<Container style={container}>{children}</Container>
			</Body>
		</Html>
	);
}

interface SignOffProps {
	/** Closing word; the original Loops templates use "Regards" or "Best". */
	close?: string;
}

/** Renders the club sign-off block ("Regards,\nDublin HEMA Club"). */
export function SignOff({ close = 'Regards' }: SignOffProps) {
	return (
		<Text style={{ ...text, whiteSpace: 'pre-line', marginBottom: 0 }}>
			{close}
			{'\n'}Dublin HEMA Club
		</Text>
	);
}

import type { TemplateMetadata } from '../src/template-metadata';

import { EmailLayout, SignOff, paragraphStyle } from './_components/layout';
import { Link, Text } from 'react-email';
import { defineTemplate } from '../src/template-metadata';

/**
 * Where the "items" link in the original Loops `inviteMember` template
 * points: HEMA Ireland, the third-party liability insurance provider.
 */
const HEMA_IRELAND_ITEMS_URL = 'https://www.hemaireland.com/';

export interface InviteMemberProps {
	/** The recipient's unique invitation acceptance link. */
	INVITATION_LINK: string;
	/**
	 * Declared because callers send them alongside the link; the original
	 * Loops template greets the recipient with a plain "Hello," and never
	 * renders the names.
	 */
	INVITEE_FIRST_NAME?: string;
	INVITEE_LAST_NAME?: string;
}

export const inviteMemberTemplate: TemplateMetadata = defineTemplate({
	kind: 'inviteMember',
	subject: "You're invited to join Dublin HEMA Club",
	from: 'Dublin HEMA Club <no-reply@mail.dublinhemaclub.com>',
	variables: [
		{ key: 'INVITEE_FIRST_NAME', type: 'string', fallback: '' },
		{ key: 'INVITEE_LAST_NAME', type: 'string', fallback: '' },
		{ key: 'INVITATION_LINK', type: 'string' },
	],
});

/** Ported verbatim from the Loops `inviteMember` transactional template. */
export default function InviteMemberEmail({
	INVITATION_LINK,
}: InviteMemberProps) {
	return (
		<EmailLayout preview="You have been invited to join Dublin HEMA Club">
			<Text style={paragraphStyle}>Hello,</Text>
			<Text style={paragraphStyle}>
				You have been invited to join DHC. Please follow{' '}
				<Link href={INVITATION_LINK}>this</Link> link and fill in your details.
				This link expires in 7 days, so please make sure you fill it out before
				that!
			</Text>
			<Text style={paragraphStyle}>
				Additionally, please purchase the following{' '}
				<Link href={HEMA_IRELAND_ITEMS_URL}>items</Link> from HEMA Ireland. This
				third-party liability insurance covers damages to third parties, items
				damaged in the sports hall during training, etc. It is not health or
				injury insurance; we encourage our members to get personal health
				insurance if they so wish.
			</Text>
			<SignOff />
		</EmailLayout>
	);
}

InviteMemberEmail.PreviewProps = {
	INVITATION_LINK: 'https://dashboard.dublinhemaclub.com/invitations/accept?token=preview',
} satisfies InviteMemberProps;

import type { TemplateMetadata } from '../src/template-metadata';

import { EmailLayout, SignOff, paragraphStyle } from './_components/layout';
import { Button, Text } from 'react-email';
import { defineTemplate } from '../src/template-metadata';

/**
 * Matches `@magic_link_validity_in_minutes` in `Dhc.Auth.PrincipalToken`;
 * the two must stay in sync because the copy tells the recipient how long
 * the link works.
 */
const MAGIC_LINK_VALIDITY_IN_MINUTES = 15;

export interface MagicLinkProps {
	/** The single-use sign-in link. */
	LOGIN_LINK: string;
}

export const magicLinkTemplate: TemplateMetadata = defineTemplate({
	kind: 'magicLink',
	subject: 'Your Dublin HEMA Club login link',
	from: 'Dublin HEMA Club <no-reply@mail.dublinhemaclub.com>',
	variables: [{ key: 'LOGIN_LINK', type: 'string' }],
});

/**
 * Inferred port of the Loops `magicLink` transactional template (the
 * original content was not exported before the migration): a single-use,
 * 15-minute sign-in link.
 */
export default function MagicLinkEmail({ LOGIN_LINK }: MagicLinkProps) {
	return (
		<EmailLayout preview="Your Dublin HEMA Club sign-in link">
			<Text style={paragraphStyle}>Hi there,</Text>
			<Text style={paragraphStyle}>
				Use the button below to sign in to your Dublin HEMA Club account:
			</Text>
			<Button href={LOGIN_LINK} style={button}>
				Log in
			</Button>
			<Text style={paragraphStyle}>
				This link expires in {MAGIC_LINK_VALIDITY_IN_MINUTES} minutes and can
				only be used once. If you didn't request it, you can safely ignore this
				email.
			</Text>
			<SignOff />
		</EmailLayout>
	);
}

const button: React.CSSProperties = {
	backgroundColor: '#111827',
	borderRadius: '6px',
	color: '#ffffff',
	display: 'inline-block',
	fontSize: '16px',
	margin: '0 0 20px',
	padding: '12px 24px',
	textDecoration: 'none',
};

