} from '../src';

describe('TEMPLATES registry', () => {
	it('covers every whitelisted Email Kind', () => {
		expect(Object.keys(TEMPLATES).sort()).toEqual([...EMAIL_KINDS].sort());
	});

	it('derives every alias mechanically from its Email Kind', () => {
		for (const kind of EMAIL_KINDS) {
			expect(TEMPLATES[kind].alias).toBe(templateAlias(kind));
		}
	});

	it('has unique aliases', () => {
		const aliases = listTemplates().map((t) => t.alias);
		expect(new Set(aliases).size).toBe(aliases.length);
	});

	it('keeps the alias of a send addressable in kebab-case', () => {
		expect(getTemplate('workshopRegistrationError').alias).toBe(
			'workshop-registration-error',
		);
	});

	it('declares at least one variable per template', () => {
		for (const template of listTemplates()) {
			expect(
				template.variables.length,
				`${template.kind} declares no variables`,
			).toBeGreaterThan(0);
		}
	});
});

